ENGINE_API bool IsDynamicBase(const FMovementBaseInterfaceData* MovementBase);

/** Determine whether MovementBase is simulating or attached to a simulating object. */
ENGINE_API bool IsSimulatedBase(const FMovementBaseInterfaceData* MovementBase);

/** Ensure that BasedObjectTick ticks after NewBase */
ENGINE_API void AddTickDependency(FTickFunction& BasedObjectTick, FMovementBaseInterfaceData* MovementBase);

/** Remove tick dependency of BasedObjectTick on OldBase */
ENGINE_API void RemoveTickDependency(FTickFunction& BasedObjectTick, FMovementBaseInterfaceData* MovementBase);

/** Determine if we should use relative positioning when based on a component (because it may move). */
inline bool UseRelativeLocation(const FMovementBaseInterfaceData* MovementBase)
{
	return IsDynamicBase(MovementBase);
}

ue_dynamic.text:
bool IsDynamicBase(const FMovementBaseInterfaceData* MovementBase)
{
	return (MovementBase && MovementBase->IsValid() && MovementBase->GetBodyInstanceOwner()->IsPhysicsOwnerMovable());
}
